@@ -189,15 +189,34 @@
  * @param event HTTP event
  * @param limit Body size limit in bytes
  */
-export async function assertBodySize(event: HTTPEvent, limit: number): Promise<void> {
-  const isWithin = await isBodySizeWithin(event, limit);
-  if (!isWithin) {
-    throw new HTTPError({
